1123→    if temp_dir.exists() {
1124→        if let Err(e) = std::fs::remove_dir_all(&temp_dir) {
1125→            log::warn!("Failed to clean temp directory: {}", e);
1126→        }
1127→    }
1128→
1129→    let status = std::process::Command::new("umount")
1130→        .arg(mount_path.to_str().unwrap())
1131→        .status()
1132→        .map_err(|e| format!("Failed to run umount: {}", e))?;
1133→
1134→    if status.success() {
1135→        log::info!("FUSE filesystem unmounted successfully");
1136→        Ok(())
1137→    } else {
1138→        // Try diskutil unmount force as fallback on macOS — Finder keeps handles open
1139→        log::info!("umount failed (likely busy), trying diskutil unmount force");

1130→        .arg(mount_path.to_str().unwrap())
1131→        .status()
1132→        .map_err(|e| format!("Failed to run umount: {}", e))?;
1133→
1134→    if status.success() {
1135→        log::info!("FUSE filesystem unmounted successfully");
1136→        Ok(())
1137→    } else {
1138→        // Try diskutil unmount force as fallback on macOS — Finder keeps handles open
1139→        log::info!("umount failed (likely busy), trying diskutil unmount force");
1140→        let status = std::process::Command::new("diskutil")
