277→/// Update the tray menu to reflect the new status.
278→///
279→/// Rebuilds the entire menu with updated item states and sets it on the tray icon.
280→/// On Error status, sends a system notification.
281→pub fn update_tray_status(app: &AppHandle, status: &TrayStatus) -> Result<(), String> {
282→    let tray = app
283→        .tray_by_id(TRAY_ID)
284→        .ok_or_else(|| "Tray icon not found".to_string())?;
285→
286→    // Rebuild the menu with updated states
287→    let menu = build_menu(app, status)?;
288→    tray.set_menu(Some(menu))
289→        .map_err(|e| format!("Failed to set tray menu: {}", e))?;
290→
291→    // Send notification on Error status
292→    if let TrayStatus::Error(ref msg) = status {
293→        if let Err(e) = send_error_notification(app, msg) {
294→            log::warn!("Failed to send error notification: {}", e);
295→        }
296→    }
297→
298→    log::debug!("Tray status updated to: {}", status.label());
299→    Ok(())
300→}
301→
302→/// Send a system notification for error states.
303→fn send_error_notification(app: &AppHandle, message: &str) -> Result<(), String> {
304→    use tauri_plugin_notification::NotificationExt;
305→    app.notification()
306→        .builder()
307→        .title("CipherBox Error")
308→        .body(message)
309→        .show()
310→        .map_err(|e| format!("Notification failed: {}", e))?;
311→    Ok(())
312→}
