232→/// Get the current time in milliseconds since Unix epoch.
233→fn now_ms() -> u64 {
234→    std::time::SystemTime::now()
235→        .duration_since(std::time::UNIX_EPOCH)
236→        .map(|d| d.as_millis() as u64)
237→        .unwrap_or(0)
