                            tauri::WebviewUrl::External("about:blank".parse().unwrap()),
                        )
                        .window_features(features)
                        .title(url.as_str())
                        .inner_size(500.0, 700.0)
                        .center()
                        .build()
                        {
                            Ok(window) => tauri::webview::NewWindowResponse::Create { window },
